//! The Windows application icon, packed as an ICO from the amigo-labs pixel
//! monogram in `assets/brand/`. Those files are generated by the website's
//! `scripts/monogram.ts` from `docs/site/project.yml`, never drawn by hand.
//! Used by build.rs and its test.

/// The monogram PNGs: 16–64 px show the small mark without frame, 128 px
/// and up the framed one.
pub const BRAND: [(u32, &[u8]); 8] = [
    (16, include_bytes!("../../assets/brand/icon-16.png")),
    (32, include_bytes!("../../assets/brand/icon-32.png")),
    (48, include_bytes!("../../assets/brand/icon-48.png")),
    (64, include_bytes!("../../assets/brand/icon-64.png")),
    (128, include_bytes!("../../assets/brand/icon-128.png")),
    (256, include_bytes!("../../assets/brand/icon-256.png")),
    (512, include_bytes!("../../assets/brand/icon-512.png")),
    (1024, include_bytes!("../../assets/brand/icon-1024.png")),
];

/// The edge of the small mark's pixel grid.
const GRID: u32 = 16;

/// The generated PNG for `size`, if `assets/brand/` has one.
pub fn png(size: u32) -> Option<&'static [u8]> {
    BRAND.iter().find(|b| b.0 == size).map(|b| b.1)
}

fn decode(data: &[u8]) -> (u32, Vec<u8>) {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(data));
    decoder.set_transformations(png::Transformations::EXPAND);
    let mut reader = decoder.read_info().expect("valid monogram png");
    let mut buf = vec![0; reader.output_buffer_size().expect("png buffer size")];
    let info = reader.next_frame(&mut buf).expect("monogram png frame");
    assert_eq!(
        (info.color_type, info.bit_depth, info.width),
        (png::ColorType::Rgba, png::BitDepth::Eight, info.height),
        "monogram png is not square 8-bit RGBA"
    );
    buf.truncate(info.buffer_size());
    (info.width, buf)
}

/// Straight-alpha RGBA pixels at `size` × `size`: the generated PNG, or for
/// a size it lacks (Windows' 20, 24 and 40 px) the small mark at the
/// largest whole scale that fits, centred on transparency, exactly as the
/// generator places its grid, so no size is blurred by scaling.
pub fn rgba(size: u32) -> Vec<u8> {
    if let Some(data) = png(size) {
        return decode(data).1;
    }
    let inner = size / GRID * GRID;
    let (w, src) = decode(png(inner).unwrap_or_else(|| panic!("no monogram for {size} px")));
    let (n, w, offset) = (size as usize, w as usize, ((size - inner) / 2) as usize);
    let mut out = vec![0u8; n * n * 4];
    for y in 0..w {
        out[((y + offset) * n + offset) * 4..][..w * 4].copy_from_slice(&src[y * w * 4..][..w * 4]);
    }
    out
}

/// A 32-bit DIB icon image: the header (height covers both bitmaps), the
/// colour bitmap bottom-up in BGRA, then the 1-bit AND mask (set where
/// fully transparent).
pub fn dib(size: u32) -> Vec<u8> {
    let px = rgba(size);
    let n = size as usize;
    let mask_stride = n.div_ceil(32) * 4;
    let mut out = Vec::with_capacity(40 + n * n * 4 + mask_stride * n);
    out.extend(40u32.to_le_bytes());
    out.extend((size as i32).to_le_bytes());
    out.extend((2 * size as i32).to_le_bytes());
    out.extend(1u16.to_le_bytes()); // planes
    out.extend(32u16.to_le_bytes()); // bits per pixel
    out.extend(0u32.to_le_bytes()); // BI_RGB
    out.extend(((n * n * 4 + mask_stride * n) as u32).to_le_bytes());
    out.extend([0u8; 16]); // resolution, palette
    for y in (0..n).rev() {
        for p in px[y * n * 4..][..n * 4].as_chunks::<4>().0 {
            out.extend([p[2], p[1], p[0], p[3]]);
        }
    }
    for y in (0..n).rev() {
        let mut row = vec![0u8; mask_stride];
        for x in 0..n {
            if px[(y * n + x) * 4 + 3] == 0 {
                row[x / 8] |= 0x80 >> (x % 8);
            }
        }
        out.extend(row);
    }
    out
}

/// An ICO file: uncompressed DIBs up to 128 px (no decoding when Windows
/// loads the small sizes at startup), the generated PNG for 256 px.
pub fn ico(sizes: &[u32]) -> Vec<u8> {
    let images: Vec<Vec<u8>> = sizes
        .iter()
        .map(|&s| match png(s) {
            Some(data) if s >= 256 => data.to_vec(),
            _ => dib(s),
        })
        .collect();
    let mut out = Vec::new();
    out.extend(0u16.to_le_bytes()); // reserved
    out.extend(1u16.to_le_bytes()); // type: icon
    out.extend((sizes.len() as u16).to_le_bytes());
    let mut offset = 6 + 16 * sizes.len();
    for (&size, image) in sizes.iter().zip(&images) {
        // 0 means 256.
        let dim = if size >= 256 { 0 } else { size as u8 };
        out.extend([dim, dim, 0, 0]); // width, height, colours, reserved
        out.extend(1u16.to_le_bytes()); // planes
        out.extend(32u16.to_le_bytes()); // bits per pixel
        out.extend((image.len() as u32).to_le_bytes());
        out.extend((offset as u32).to_le_bytes());
        offset += image.len();
    }
    for image in images {
        out.extend(image);
    }
    out
}
